-- Live Google Places scrape across 30 cities + researched events
-- (generated by the parallel scrape run). Requires migrations through 0023.
-- Re-runnable: every insert is guarded against duplicates.
-- google_refreshed_at stays NULL so the next "Enrich all" pass fetches the
-- photo and structured hours for each of these in one details call.

insert into places (name, kind, address, city_id, location, website, source, source_url,
  confidence, status, google_place_id, rating, rating_count, phone, gmaps_url,
  opening_hours, business_status)
select 'ABCHESS', 'club', '71-75 Shelton St, London WC2H 9JQ, UK', c.id,
  st_setsrid(st_makepoint(-0.1235842, 51.5149037), 4326)::geography,
  'https://abchess.org/forkids', 'google', 'https://maps.google.com/?cid=1349843732499459900&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA',
  0.8, 'approved', 'ChIJO2ancikFdkgRPO_qEbmbuxI', 5, 19,
  '+44 20 3290 2111', 'https://maps.google.com/?cid=1349843732499459900&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA', '{"weekday":["Monday: Open 24 hours","Tuesday: Open 24 hours","Wednesday: Open 24 hours","Thursday: Open 24 hours","Friday: Open 24 hours","Saturday: Open 24 hours","Sunday: Open 24 hours"],"utc_offset_minutes":60}'::jsonb, 'OPERATIONAL'
from cities c
where c.slug = 'london'
  and not exists (select 1 from places x where x.google_place_id = 'ChIJO2ancikFdkgRPO_qEbmbuxI')
  and not exists (select 1 from places x where x.city_id = c.id and lower(x.name) = lower('ABCHESS'));

